#!/usr/bin/env node
/**
 * ULS Sync Utility
 * 
 * Syncs latest changes from ULS_V2.0 repository while preserving user customizations.
 * 
 * What it syncs:
 * - Custom demo pages (updates master features, preserves custom features)
 * - ULS components (adds new components from ULS, preserves user's custom components)
 * 
 * What it preserves:
 * - User's overrides folder (never touched)
 * - User's custom components in uls-components
 * - User's custom features in custom-demo pages
 * 
 * Usage:
 *   npm run uls-sync
 *   npx uls-sync
 */

const fs = require('fs');
const path = require('path');

// ==========================================================================
// UTILITY FUNCTIONS
// ==========================================================================

function findULSPackage() {
  const projectRoot = process.cwd();
  
  const candidates = [
    path.resolve(projectRoot, 'node_modules/uls-v2'),
    path.resolve(__dirname, '..'),
    path.resolve(projectRoot, 'node_modules/@uls/v2'),
  ];
  
  for (const candidate of candidates) {
    const primereactPath = path.join(candidate, 'src/libs/uls-primereact');
    if (fs.existsSync(primereactPath)) {
      return candidate;
    }
  }
  
  return null;
}

function findProjectRoot() {
  // Look for project root (where uls-init was run)
  const currentDir = process.cwd();
  
  // Check if we're in a project with ULS structure
  const ulsStylesPath = path.join(currentDir, 'src/styles/uls');
  if (fs.existsSync(ulsStylesPath)) {
    return currentDir;
  }
  
  // Check parent directories
  let dir = currentDir;
  for (let i = 0; i < 5; i++) {
    const checkPath = path.join(dir, 'src/styles/uls');
    if (fs.existsSync(checkPath)) {
      return dir;
    }
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  
  return currentDir;
}

function generateComponentVariations(componentName) {
  const pascalCase = componentName.charAt(0).toUpperCase() + componentName.slice(1);
  return {
    ComponentName: pascalCase,
    componentName: componentName.charAt(0).toLowerCase() + componentName.slice(1)
  };
}

function getULSVersion() {
  const ulsPackage = findULSPackage();
  if (!ulsPackage) {
    return 'unknown';
  }
  
  const packageJsonPath = path.join(ulsPackage, 'package.json');
  if (fs.existsSync(packageJsonPath)) {
    try {
      const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
      return pkg.version || 'unknown';
    } catch (error) {
      return 'unknown';
    }
  }
  return 'unknown';
}

// ==========================================================================
// CUSTOM DEMO SYNC
// ==========================================================================

function extractFeatureIds(featuresContent) {
  const idMatches = [...featuresContent.matchAll(/id:\s*["']([^"']+)["']/g)];
  return idMatches.map(match => match[1]);
}

async function syncCustomDemoPage(componentName, ulsPackage, projectRoot) {
  const primereactPath = path.join(ulsPackage, 'src/libs/uls-primereact');
  const variations = generateComponentVariations(componentName);
  
  // Paths
  const masterFeaturesPath = path.join(
    primereactPath,
    'src/Pages/Documentation/UiComponents',
    `${variations.ComponentName}Page/features.jsx`
  );
  
  // Check if custom demo exists in project
  const projectCustomDemoPath = path.join(projectRoot, 'src/demo/uls-primereact/src/custom-demo');
  const componentPagePath = path.join(projectCustomDemoPath, `${variations.ComponentName}Page`);
  const customFeaturesPath = path.join(componentPagePath, 'features.jsx');
  const versionPath = path.join(componentPagePath, '.uls-sync/version.json');
  
  // Check if custom demo exists
  if (!fs.existsSync(customFeaturesPath)) {
    return { status: 'skipped', reason: 'Custom demo not found' };
  }
  
  // Check if master features exist
  if (!fs.existsSync(masterFeaturesPath)) {
    return { status: 'error', reason: 'Master features not found' };
  }
  
  // Read files
  const masterFeaturesContent = fs.readFileSync(masterFeaturesPath, 'utf8');
  const customFeaturesContent = fs.readFileSync(customFeaturesPath, 'utf8');
  
  // Extract feature IDs for comparison
  const masterIds = extractFeatureIds(masterFeaturesContent);
  
  // Read version info
  let versionInfo = null;
  if (fs.existsSync(versionPath)) {
    try {
      versionInfo = JSON.parse(fs.readFileSync(versionPath, 'utf8'));
    } catch (error) {
      // Will create new version info
    }
  }
  
  // Check if master features have changed
  const storedMasterIds = versionInfo?.masterSnapshot || [];
  const masterChanged = JSON.stringify(masterIds.sort()) !== JSON.stringify(storedMasterIds.sort());
  
  if (!masterChanged) {
    return { status: 'up-to-date', masterCount: masterIds.length };
  }
  
  // Verify import path is correct
  const importPathRegex = /import\s*{\s*\w+FeatureItems\s+as\s+Master\w+FeatureItems\s*}\s+from\s+['"]([^'"]+)['"]/;
  const importMatch = customFeaturesContent.match(importPathRegex);
  
  if (importMatch) {
    const currentImportPath = importMatch[1];
    const expectedImportPath = `../../Pages/Documentation/UiComponents/${variations.ComponentName}Page/features`;
    
    if (currentImportPath !== expectedImportPath) {
      // Update import path
      const updatedContent = customFeaturesContent.replace(
        importPathRegex,
        `import { ${variations.ComponentName}FeatureItems as Master${variations.ComponentName}FeatureItems } from '${expectedImportPath}'`
      );
      
      fs.writeFileSync(customFeaturesPath, updatedContent, 'utf8');
    }
  }
  
  // Update version info
  const ulsVersion = getULSVersion();
  const timestamp = new Date().toISOString();
  
  if (!versionInfo) {
    versionInfo = {
      ulsVersion: ulsVersion,
      demoVersion: "1.0.0",
      lastSync: timestamp,
      history: [],
      masterSnapshot: []
    };
  }
  
  // Add to history
  versionInfo.history.push({
    demoVersion: versionInfo.demoVersion,
    ulsVersion: ulsVersion,
    synced: timestamp,
    changes: `Master features updated: ${masterIds.length} total features`
  });
  
  // Update snapshot
  versionInfo.masterSnapshot = masterIds;
  versionInfo.lastSync = timestamp;
  versionInfo.ulsVersion = ulsVersion;
  
  // Ensure .uls-sync directory exists
  const syncDir = path.dirname(versionPath);
  if (!fs.existsSync(syncDir)) {
    fs.mkdirSync(syncDir, { recursive: true });
  }
  
  // Save version info
  fs.writeFileSync(versionPath, JSON.stringify(versionInfo, null, 2), 'utf8');
  
  const added = masterIds.filter(id => !storedMasterIds.includes(id));
  const removed = storedMasterIds.filter(id => !masterIds.includes(id));
  
  return {
    status: 'synced',
    masterCount: masterIds.length,
    added: added.length,
    removed: removed.length
  };
}

// ==========================================================================
// ULS COMPONENTS SYNC
// ==========================================================================

function getIgnoredComponents(projectRoot) {
  const ignoredPath = path.join(projectRoot, 'src/uls-components/.uls-sync/ignored-components.json');
  if (fs.existsSync(ignoredPath)) {
    try {
      const content = fs.readFileSync(ignoredPath, 'utf8');
      const data = JSON.parse(content);
      return new Set(data.ignored || []);
    } catch (error) {
      return new Set();
    }
  }
  return new Set();
}

function syncULSComponents(ulsPackage, projectRoot) {
  // ULS components source (from ULS package)
  const ulsComponentsSource = path.join(ulsPackage, 'src/uls-components/src/components');
  // Project's ULS components (synced from ULS)
  const projectComponentsPath = path.join(projectRoot, 'src/uls-components/src/components');
  // Project's custom components (user-written, never touched)
  const projectCustomComponentsPath = path.join(projectRoot, 'src/uls-components/src/custom-components');
  
  if (!fs.existsSync(ulsComponentsSource)) {
    return { status: 'skipped', reason: 'ULS components source not found' };
  }
  
  // Ensure project components directory exists (ULS components only)
  if (!fs.existsSync(projectComponentsPath)) {
    fs.mkdirSync(projectComponentsPath, { recursive: true });
  }
  
  // Ensure custom-components directory exists (user components, never synced)
  if (!fs.existsSync(projectCustomComponentsPath)) {
    fs.mkdirSync(projectCustomComponentsPath, { recursive: true });
  }
  
  // Get ignored components (user-deleted components that should not be synced)
  const ignoredComponents = getIgnoredComponents(projectRoot);
  
  // Get components from ULS package (components folder only)
  let ulsComponents = [];
  try {
    ulsComponents = fs.readdirSync(ulsComponentsSource, { withFileTypes: true })
      .filter(dirent => dirent.isDirectory())
      .map(dirent => dirent.name)
      .filter(name => !ignoredComponents.has(name)); // Filter out ignored components
  } catch (error) {
    // Directory might be empty or have permission issues
    return { 
      status: 'skipped', 
      reason: `Could not read ULS components directory: ${error.message}`,
      note: 'The components directory may be empty or inaccessible'
    };
  }
  
  // If no components found, return early but don't treat as error
  if (ulsComponents.length === 0) {
    return {
      status: 'skipped',
      reason: 'No components found in ULS package',
      note: 'Components will be synced when they are added to the ULS package'
    };
  }
  
  // Get existing ULS components in project (components folder only)
  const existingComponents = fs.existsSync(projectComponentsPath)
    ? fs.readdirSync(projectComponentsPath, { withFileTypes: true })
        .filter(dirent => dirent.isDirectory())
        .map(dirent => dirent.name)
    : [];
  
  // Get user's custom components (custom-components folder - never touched)
  const userCustomComponents = fs.existsSync(projectCustomComponentsPath)
    ? fs.readdirSync(projectCustomComponentsPath, { withFileTypes: true })
        .filter(dirent => dirent.isDirectory())
        .map(dirent => dirent.name)
    : [];
  
  const results = {
    added: [],
    updated: [],
    preserved: [],
    skipped: [],
    ignored: [],
    customComponentsPreserved: userCustomComponents.length
  };
  
  // Track components that exist in ULS but are ignored
  let ulsComponentsAll = [];
  if (fs.existsSync(ulsComponentsSource)) {
    try {
      ulsComponentsAll = fs.readdirSync(ulsComponentsSource, { withFileTypes: true })
        .filter(dirent => dirent.isDirectory())
        .map(dirent => dirent.name);
    } catch (error) {
      // Directory might be empty or have permission issues
    }
  }
  const ignoredInULS = ulsComponentsAll.filter(name => ignoredComponents.has(name));
  if (ignoredInULS.length > 0) {
    results.ignored = ignoredInULS;
  }
  
  // Sync each ULS component (only from components folder, excluding ignored)
  for (const componentName of ulsComponents) {
    const sourceComponentPath = path.join(ulsComponentsSource, componentName);
    const destComponentPath = path.join(projectComponentsPath, componentName);
    
    if (!fs.existsSync(destComponentPath)) {
      // New component - copy it
      copyDirectory(sourceComponentPath, destComponentPath);
      results.added.push(componentName);
    } else {
      // Component exists - check if it matches ULS structure
      const sourceFiles = getComponentFiles(sourceComponentPath);
      const destFiles = getComponentFiles(destComponentPath);
      
      // If structure matches, update; otherwise preserve user's version
      if (hasSameStructure(sourceFiles, destFiles)) {
        // Update component files
        copyDirectory(sourceComponentPath, destComponentPath);
        results.updated.push(componentName);
      } else {
        // Preserve user's modified component (different structure = user modified)
        results.preserved.push(componentName);
      }
    }
  }
  
  // Check for components that exist in ULS but were deleted locally
  // Only add to ignored if they were previously synced (existed before)
  // We detect this by checking if they're in ULS but not in project and not already ignored
  // Note: This will add them to ignored on first sync after deletion
  const componentsInULSButNotLocal = ulsComponentsAll.filter(name => 
    !existingComponents.includes(name) && !ignoredComponents.has(name)
  );
  
  // If components exist in ULS but not locally, they were likely deleted by user
  // Add them to ignored list so they won't be re-added
  if (componentsInULSButNotLocal.length > 0) {
    const syncDir = path.join(projectRoot, 'src/uls-components/.uls-sync');
    if (!fs.existsSync(syncDir)) {
      fs.mkdirSync(syncDir, { recursive: true });
    }
    
    const ignoredPath = path.join(syncDir, 'ignored-components.json');
    const currentIgnored = Array.from(ignoredComponents);
    const newIgnored = [...new Set([...currentIgnored, ...componentsInULSButNotLocal])];
    
    fs.writeFileSync(ignoredPath, JSON.stringify({ ignored: newIgnored }, null, 2), 'utf8');
    
    // Update results
    results.ignored = newIgnored;
  } else if (ignoredComponents.size > 0) {
    // Just track existing ignored components
    results.ignored = Array.from(ignoredComponents);
  }
  
  // Remove components that no longer exist in ULS (cleanup)
  // Check against ALL components in ULS (not just non-ignored ones)
  // This ensures components deleted from ULS are removed from project, even if they were ignored
  const componentsToRemove = existingComponents.filter(c => {
    // Component exists in project but not in ULS package at all
    return !ulsComponentsAll.includes(c);
  });
  
  for (const componentName of componentsToRemove) {
    const componentPath = path.join(projectComponentsPath, componentName);
    if (fs.existsSync(componentPath)) {
      // Only remove if it's not in custom-components (safety check)
      const customComponentPath = path.join(projectCustomComponentsPath, componentName);
      if (!fs.existsSync(customComponentPath)) {
        // Remove the component directory
        fs.rmSync(componentPath, { recursive: true, force: true });
        results.removed = results.removed || [];
        results.removed.push(componentName);
        
        // Also remove from ignored list if it was there (since ULS removed it)
        if (ignoredComponents.has(componentName)) {
          const syncDir = path.join(projectRoot, 'src/uls-components/.uls-sync');
          if (fs.existsSync(syncDir)) {
            const ignoredPath = path.join(syncDir, 'ignored-components.json');
            const currentIgnored = Array.from(ignoredComponents);
            const updatedIgnored = currentIgnored.filter(c => c !== componentName);
            fs.writeFileSync(ignoredPath, JSON.stringify({ ignored: updatedIgnored }, null, 2), 'utf8');
          }
        }
      }
    }
  }
  
  // Update index.js to export all components (ULS components + user custom components)
  // Export from both components/ and custom-components/ folders
  // Only export components that are not ignored
  const finalIgnoredSet = results.ignored ? new Set(results.ignored) : ignoredComponents;
  const componentsToExport = ulsComponents.filter(c => !finalIgnoredSet.has(c));
  if (componentsToExport.length > 0 || userCustomComponents.length > 0) {
    updateComponentsIndex(projectRoot, componentsToExport, userCustomComponents);
  }
  
  return results;
}

// ==========================================================================
// DEMO APP STRUCTURE SYNC
// ==========================================================================

function syncDemoAppStructure(ulsPackage, projectRoot) {
  const primereactPath = path.join(ulsPackage, 'src/libs/uls-primereact');
  const projectDemoPath = path.join(projectRoot, 'src/demo/uls-primereact/src');
  
  const results = {
    customComponentsAdded: 0,
    customDemoPagesAdded: 0,
    registeredPagesAdded: 0,
    customComponentsRemoved: [],
    customDemoPagesRemoved: [],
    registeredPagesRemoved: []
  };
  
  // Ensure demo app src directory exists
  if (!fs.existsSync(projectDemoPath)) {
    fs.mkdirSync(projectDemoPath, { recursive: true });
  }
  
  // Ensure Pages/Documentation/UiComponents directory exists
  const projectUiComponentsPath = path.join(projectDemoPath, 'Pages/Documentation/UiComponents');
  if (!fs.existsSync(projectUiComponentsPath)) {
    fs.mkdirSync(projectUiComponentsPath, { recursive: true });
  }
  
  // 1. Sync custom-components from ULS to project
  const ulsCustomComponentsPath = path.join(primereactPath, 'src/custom-components');
  const projectCustomComponentsPath = path.join(projectDemoPath, 'custom-components');
  
  // Ensure project custom-components directory exists
  if (!fs.existsSync(projectCustomComponentsPath)) {
    fs.mkdirSync(projectCustomComponentsPath, { recursive: true });
  }
  
  // Get existing project custom components (always check, even if ULS folder doesn't exist)
  let existingCustomComponents = [];
  try {
    existingCustomComponents = fs.readdirSync(projectCustomComponentsPath, { withFileTypes: true })
      .filter(dirent => dirent.isDirectory())
      .map(dirent => dirent.name);
  } catch (error) {
    // Directory might be empty
  }
  
  // Get ULS custom components (if folder exists)
  let ulsCustomComponents = [];
  if (fs.existsSync(ulsCustomComponentsPath)) {
    try {
      ulsCustomComponents = fs.readdirSync(ulsCustomComponentsPath, { withFileTypes: true })
        .filter(dirent => dirent.isDirectory())
        .map(dirent => dirent.name);
    } catch (error) {
      // Directory might be empty
    }
    
    // Sync components from ULS (add new, update existing)
    for (const componentName of ulsCustomComponents) {
      const sourcePath = path.join(ulsCustomComponentsPath, componentName);
      const destPath = path.join(projectCustomComponentsPath, componentName);
      
      if (!fs.existsSync(destPath)) {
        // New component from ULS - copy it
        copyDirectory(sourcePath, destPath);
        results.customComponentsAdded++;
      } else {
        // Component exists - update it from ULS (user can customize in their own folders)
        copyDirectory(sourcePath, destPath);
        // Don't increment added count, but we did update it
      }
    }
  }
  
  // Remove custom-components that no longer exist in ULS (cleanup)
  // This handles both: ULS folder doesn't exist, or components were removed from ULS
  const customComponentsToRemove = existingCustomComponents.filter(c => !ulsCustomComponents.includes(c));
  for (const componentName of customComponentsToRemove) {
    const componentPath = path.join(projectCustomComponentsPath, componentName);
    if (fs.existsSync(componentPath)) {
      // Remove the custom-component directory
      fs.rmSync(componentPath, { recursive: true, force: true });
      results.customComponentsRemoved.push(componentName);
    }
  }
  
  // 2. Sync custom-demo pages from ULS to project
  const ulsCustomDemoPath = path.join(primereactPath, 'src/custom-demo');
  const projectCustomDemoPath = path.join(projectDemoPath, 'custom-demo');
  
  // Ensure project custom-demo directory exists
  if (!fs.existsSync(projectCustomDemoPath)) {
    fs.mkdirSync(projectCustomDemoPath, { recursive: true });
  }
  
  // Get existing project custom demo pages (always check, even if ULS folder doesn't exist)
  let existingCustomDemoPages = [];
  try {
    existingCustomDemoPages = fs.readdirSync(projectCustomDemoPath, { withFileTypes: true })
      .filter(dirent => dirent.isDirectory() && dirent.name.endsWith('Page'))
      .map(dirent => dirent.name);
  } catch (error) {
    // Directory might be empty
  }
  
  // Get ULS custom demo pages (if folder exists)
  let ulsCustomDemoPages = [];
  if (fs.existsSync(ulsCustomDemoPath)) {
    try {
      ulsCustomDemoPages = fs.readdirSync(ulsCustomDemoPath, { withFileTypes: true })
        .filter(dirent => dirent.isDirectory() && dirent.name.endsWith('Page'))
        .map(dirent => dirent.name);
    } catch (error) {
      // Directory might be empty
    }
    
    // Sync demo pages from ULS (add new, update existing)
    for (const pageName of ulsCustomDemoPages) {
      const sourcePath = path.join(ulsCustomDemoPath, pageName);
      const destPath = path.join(projectCustomDemoPath, pageName);
      
      if (!fs.existsSync(destPath)) {
        // New demo page from ULS - copy it
        copyDirectory(sourcePath, destPath);
        results.customDemoPagesAdded++;
      } else {
        // Demo page exists - update it from ULS (user can customize in their own folders)
        copyDirectory(sourcePath, destPath);
        // Don't increment added count, but we did update it
      }
    }
  }
  
  // Remove custom-demo pages that no longer exist in ULS (cleanup)
  // This handles both: ULS folder doesn't exist, or pages were removed from ULS
  const customDemoPagesToRemove = existingCustomDemoPages.filter(pageName => !ulsCustomDemoPages.includes(pageName));
  for (const pageName of customDemoPagesToRemove) {
    const pagePath = path.join(projectCustomDemoPath, pageName);
    if (fs.existsSync(pagePath)) {
      // Remove the custom-demo page directory
      fs.rmSync(pagePath, { recursive: true, force: true });
      results.customDemoPagesRemoved.push(pageName);
    }
  }
  
  // 3. Sync registered ULS component pages from Pages/Documentation/UiComponents
  // These are ULS component demo pages that have been registered in the main navigation
  const ulsUiComponentsPath = path.join(primereactPath, 'src/Pages/Documentation/UiComponents');
  
  // Get existing project registered pages (always check, even if ULS folder doesn't exist)
  let existingRegisteredPages = [];
  try {
    existingRegisteredPages = fs.readdirSync(projectUiComponentsPath, { withFileTypes: true })
      .filter(dirent => dirent.isDirectory() && dirent.name.endsWith('Page'))
      .map(dirent => dirent.name);
  } catch (error) {
    // Directory might be empty
  }
  
  // Get ULS registered component pages (if folder exists)
  // Only include pages that have meta.js (indicates registered ULS component pages)
  let ulsRegisteredPages = [];
  if (fs.existsSync(ulsUiComponentsPath)) {
    try {
      ulsRegisteredPages = fs.readdirSync(ulsUiComponentsPath, { withFileTypes: true })
        .filter(dirent => {
          if (!dirent.isDirectory() || !dirent.name.endsWith('Page')) {
            return false;
          }
          // Check if it has meta.js (indicates it's a registered component page)
          const metaPath = path.join(ulsUiComponentsPath, dirent.name, 'meta.js');
          return fs.existsSync(metaPath);
        })
        .map(dirent => dirent.name);
    } catch (error) {
      // Directory might be empty
    }
    
    // Sync registered pages from ULS (add new, update existing)
    for (const pageName of ulsRegisteredPages) {
      const sourcePath = path.join(ulsUiComponentsPath, pageName);
      const destPath = path.join(projectUiComponentsPath, pageName);
      
      if (!fs.existsSync(destPath)) {
        // New registered page from ULS - copy it
        copyDirectory(sourcePath, destPath);
        results.registeredPagesAdded++;
      } else {
        // Page exists - update it from ULS
        copyDirectory(sourcePath, destPath);
        // Don't increment count, but we did update it
      }
    }
  }
  
  // Remove registered pages that no longer exist in ULS (cleanup)
  // This handles both: ULS folder doesn't exist, or pages were removed from ULS
  // Only remove pages that look like ULS component pages (have meta.js with ULS Components category)
  const registeredPagesToRemove = existingRegisteredPages.filter(pageName => {
    // Check if page exists in ULS
    if (ulsRegisteredPages.includes(pageName)) {
      return false; // Keep it, it exists in ULS
    }
    
    // Check if it's a ULS component page (has meta.js with ULS Components category)
    const pageMetaPath = path.join(projectUiComponentsPath, pageName, 'meta.js');
    if (fs.existsSync(pageMetaPath)) {
      try {
        const metaContent = fs.readFileSync(pageMetaPath, 'utf8');
        // Check if it's a ULS component page (category: 'ULS Components')
        if (metaContent.includes("category: 'ULS Components'") || 
            metaContent.includes('category: "ULS Components"')) {
          return true; // Remove it, it's a ULS component page that no longer exists in ULS
        }
      } catch (error) {
        // Can't read meta, skip removal to be safe
      }
    }
    
    return false; // Don't remove if we can't determine it's a ULS component page
  });
  
  for (const pageName of registeredPagesToRemove) {
    const pagePath = path.join(projectUiComponentsPath, pageName);
    if (fs.existsSync(pagePath)) {
      // Remove the registered page directory
      fs.rmSync(pagePath, { recursive: true, force: true });
      results.registeredPagesRemoved.push(pageName);
    }
  }
  
  return results;
}

function getComponentFiles(componentPath) {
  if (!fs.existsSync(componentPath)) {
    return [];
  }
  
  const files = [];
  const entries = fs.readdirSync(componentPath, { withFileTypes: true });
  
  for (const entry of entries) {
    if (entry.isFile()) {
      files.push(entry.name);
    } else if (entry.isDirectory()) {
      // Recursively get files from subdirectories
      const subFiles = getComponentFiles(path.join(componentPath, entry.name));
      files.push(...subFiles.map(f => `${entry.name}/${f}`));
    }
  }
  
  return files.sort();
}

function hasSameStructure(sourceFiles, destFiles) {
  // Check if both have the same core files (component file and index)
  const sourceCore = sourceFiles.filter(f => f.includes('index') || f.endsWith('.jsx') || f.endsWith('.js'));
  const destCore = destFiles.filter(f => f.includes('index') || f.endsWith('.jsx') || f.endsWith('.js'));
  
  // If core files match, consider it the same structure
  return JSON.stringify(sourceCore.sort()) === JSON.stringify(destCore.sort());
}

function copyDirectory(sourceDir, destDir) {
  if (!fs.existsSync(sourceDir)) {
    return;
  }
  
  // Ensure destination exists
  if (!fs.existsSync(destDir)) {
    fs.mkdirSync(destDir, { recursive: true });
  }
  
  const entries = fs.readdirSync(sourceDir, { withFileTypes: true });
  
  for (const entry of entries) {
    const sourcePath = path.join(sourceDir, entry.name);
    const destPath = path.join(destDir, entry.name);
    
    if (entry.isDirectory()) {
      copyDirectory(sourcePath, destPath);
    } else {
      fs.copyFileSync(sourcePath, destPath);
    }
  }
}

function updateComponentsIndex(projectRoot, ulsComponentNames, customComponentNames = []) {
  const indexPath = path.join(projectRoot, 'src/uls-components/src/index.js');
  
  // Ensure directory exists
  const indexDir = path.dirname(indexPath);
  if (!fs.existsSync(indexDir)) {
    fs.mkdirSync(indexDir, { recursive: true });
  }
  
  const exports = [];
  
  // Export ULS components from components/ folder
  for (const name of ulsComponentNames) {
    const baseName = name.startsWith('uls-') ? name.replace('uls-', '') : name;
    const variations = generateComponentVariations(baseName);
    
    // Check what the component actually exports
    const componentIndexPath = path.join(projectRoot, 'src/uls-components/src/components', name, 'index.js');
    if (fs.existsSync(componentIndexPath)) {
      const indexContent = fs.readFileSync(componentIndexPath, 'utf8');
      // Try to find the export name
      const exportMatch = indexContent.match(/export\s+(?:{\s*(\w+)\s*}|default\s+(\w+))/);
      if (exportMatch) {
        const exportName = exportMatch[1] || exportMatch[2];
        exports.push(`export { ${exportName} } from './components/${name}';`);
        continue;
      }
    }
    
    // Fallback to generated name
    exports.push(`export { ${variations.ComponentName} } from './components/${name}';`);
  }
  
  // Export user custom components from custom-components/ folder
  for (const name of customComponentNames) {
    const baseName = name.startsWith('uls-') ? name.replace('uls-', '') : name;
    const variations = generateComponentVariations(baseName);
    
    // Check what the component actually exports
    const componentIndexPath = path.join(projectRoot, 'src/uls-components/src/custom-components', name, 'index.js');
    if (fs.existsSync(componentIndexPath)) {
      const indexContent = fs.readFileSync(componentIndexPath, 'utf8');
      // Try to find the export name
      const exportMatch = indexContent.match(/export\s+(?:{\s*(\w+)\s*}|default\s+(\w+))/);
      if (exportMatch) {
        const exportName = exportMatch[1] || exportMatch[2];
        exports.push(`export { ${exportName} } from './custom-components/${name}';`);
        continue;
      }
    }
    
    // Fallback to generated name
    exports.push(`export { ${variations.ComponentName} } from './custom-components/${name}';`);
  }
  
  const content = `// ==========================================================================
// ULS Components Library
// ==========================================================================
// React component library built on top of ULS design system
// Export all components for easy importing
// ==========================================================================

${exports.length > 0 ? exports.join('\n') : '// No components exported'}
`;
  
  fs.writeFileSync(indexPath, content, 'utf8');
}

// ==========================================================================
// VITE CONFIG UPDATE
// ==========================================================================

function updateViteConfig(projectRoot) {
  const viteConfigPath = path.join(projectRoot, 'src/demo/uls-primereact/vite.config.js');
  
  if (!fs.existsSync(viteConfigPath)) {
    return { updated: false, reason: 'vite.config.js not found' };
  }
  
  let viteConfigContent = fs.readFileSync(viteConfigPath, 'utf8');
  const originalContent = viteConfigContent;
  
  // Check if it already has the new logic (checks project's src/uls-components first)
  if (viteConfigContent.includes('projectComponents = path.resolve(__dirname') && 
      viteConfigContent.includes('fs.existsSync(projectComponents)')) {
    return { updated: false, reason: 'Already using correct alias logic' };
  }
  
  // Pattern to find the old @uls/components alias
  // Matches: '@uls/components': path.resolve(__dirname, '../../../node_modules/uls-v2/src/uls-components/src'),
  const oldAliasPattern = /(['"]@uls\/components['"]\s*:\s*)path\.resolve\(__dirname,\s*['"][^'"]*node_modules[^'"]*uls-v2[^'"]*uls-components[^'"]*['"]\)/;
  
  if (!oldAliasPattern.test(viteConfigContent)) {
    // Check if it's a different pattern (maybe already updated or different format)
    if (viteConfigContent.includes("'@uls/components'") || viteConfigContent.includes('"@uls/components"')) {
      // Has the alias but not in the expected format - try to update it anyway
      const aliasPattern = /(['"]@uls\/components['"]\s*:\s*)([^,}]+)/;
      const match = viteConfigContent.match(aliasPattern);
      if (match) {
        const newAlias = `$1(() => {
        const projectComponents = path.resolve(__dirname, '../../../src/uls-components/src');
        const nodeModulesComponents = path.resolve(__dirname, '../../../node_modules/uls-v2/src/uls-components/src');
        // Prefer project's custom components if they exist
        if (fs.existsSync(projectComponents)) {
          return projectComponents;
        }
        return nodeModulesComponents;
      })()`;
        viteConfigContent = viteConfigContent.replace(aliasPattern, newAlias);
      }
    } else {
      return { updated: false, reason: 'Could not find @uls/components alias to update' };
    }
  } else {
    // Replace with new logic
    const newAlias = `$1(() => {
        const projectComponents = path.resolve(__dirname, '../../../src/uls-components/src');
        const nodeModulesComponents = path.resolve(__dirname, '../../../node_modules/uls-v2/src/uls-components/src');
        // Prefer project's custom components if they exist
        if (fs.existsSync(projectComponents)) {
          return projectComponents;
        }
        return nodeModulesComponents;
      })()`;
    viteConfigContent = viteConfigContent.replace(oldAliasPattern, newAlias);
  }
  
  // Only write if content changed
  if (viteConfigContent !== originalContent) {
    fs.writeFileSync(viteConfigPath, viteConfigContent, 'utf8');
    return { updated: true, path: viteConfigPath };
  }
  
  return { updated: false, reason: 'No changes needed' };
}

// ==========================================================================
// MAIN SYNC FUNCTION
// ==========================================================================

async function syncULS() {
  try {
    console.log('\n🔄 ULS Sync Utility');
    console.log('═'.repeat(60));
    
    // Find ULS package
    const ulsPackage = findULSPackage();
    if (!ulsPackage) {
      throw new Error('ULS package not found. Make sure uls-v2 is installed or you are running from ULS workspace.');
    }
    
    console.log(`\n📦 Found ULS package: ${path.relative(process.cwd(), ulsPackage)}`);
    console.log(`   Version: ${getULSVersion()}\n`);
    
    // Find project root
    const projectRoot = findProjectRoot();
    console.log(`📁 Project root: ${path.relative(process.cwd(), projectRoot)}\n`);
    
    // Verify overrides folder exists and is protected
    const overridesPath = path.join(projectRoot, 'src/styles/uls/overrides');
    if (fs.existsSync(overridesPath)) {
      console.log('✅ Overrides folder detected - will be preserved (not synced)');
    }
    
    // Update vite.config.js if needed (to support custom components)
    console.log('\n⚙️  Checking vite.config.js...');
    const viteConfigUpdate = updateViteConfig(projectRoot);
    if (viteConfigUpdate.updated) {
      console.log(`   ✅ Updated vite.config.js to support custom components`);
      console.log(`      ${path.relative(process.cwd(), viteConfigUpdate.path)}`);
      console.log(`      Restart your dev server for changes to take effect.`);
    } else if (viteConfigUpdate.reason === 'Already using correct alias logic') {
      console.log(`   ✓ vite.config.js already configured correctly`);
    } else {
      console.log(`   ⚠️  ${viteConfigUpdate.reason}`);
    }
    
    console.log('\n' + '═'.repeat(60));
    console.log('\n🚀 Starting sync process...\n');
    
    const results = {
      customDemos: [],
      components: null
    };
    
    // 0. Sync demo app structure (custom-components, custom-demo, and registered pages)
    console.log('📋 Syncing demo app structure...\n');
    const demoAppSyncResult = syncDemoAppStructure(ulsPackage, projectRoot);
    if (demoAppSyncResult.customComponentsAdded > 0) {
      console.log(`   ✅ Added/Updated ${demoAppSyncResult.customComponentsAdded} demo components from ULS`);
    }
    if (demoAppSyncResult.customDemoPagesAdded > 0) {
      console.log(`   ✅ Added/Updated ${demoAppSyncResult.customDemoPagesAdded} demo pages from ULS`);
    }
    if (demoAppSyncResult.registeredPagesAdded > 0) {
      console.log(`   ✅ Added/Updated ${demoAppSyncResult.registeredPagesAdded} registered component pages from ULS`);
    }
    if (demoAppSyncResult.customComponentsRemoved && demoAppSyncResult.customComponentsRemoved.length > 0) {
      console.log(`   🗑️  Removed ${demoAppSyncResult.customComponentsRemoved.length} demo components: ${demoAppSyncResult.customComponentsRemoved.join(', ')}`);
    }
    if (demoAppSyncResult.customDemoPagesRemoved && demoAppSyncResult.customDemoPagesRemoved.length > 0) {
      console.log(`   🗑️  Removed ${demoAppSyncResult.customDemoPagesRemoved.length} demo pages: ${demoAppSyncResult.customDemoPagesRemoved.join(', ')}`);
    }
    if (demoAppSyncResult.registeredPagesRemoved && demoAppSyncResult.registeredPagesRemoved.length > 0) {
      console.log(`   🗑️  Removed ${demoAppSyncResult.registeredPagesRemoved.length} registered pages: ${demoAppSyncResult.registeredPagesRemoved.join(', ')}`);
    }
    if (demoAppSyncResult.customComponentsAdded === 0 && 
        demoAppSyncResult.customDemoPagesAdded === 0 && 
        demoAppSyncResult.registeredPagesAdded === 0 &&
        (!demoAppSyncResult.customComponentsRemoved || demoAppSyncResult.customComponentsRemoved.length === 0) &&
        (!demoAppSyncResult.customDemoPagesRemoved || demoAppSyncResult.customDemoPagesRemoved.length === 0) &&
        (!demoAppSyncResult.registeredPagesRemoved || demoAppSyncResult.registeredPagesRemoved.length === 0)) {
      console.log(`   ✓ Demo app structure up to date`);
    }
    
    // 1. Sync custom demo pages (update existing pages)
    console.log('\n📋 Syncing custom demo pages...\n');
    const customDemoPath = path.join(projectRoot, 'src/demo/uls-primereact/src/custom-demo');
    
    if (fs.existsSync(customDemoPath)) {
      const customDemoFolders = fs.readdirSync(customDemoPath, { withFileTypes: true })
        .filter(dirent => dirent.isDirectory() && dirent.name.endsWith('Page'))
        .map(dirent => dirent.name);
      
      if (customDemoFolders.length > 0) {
        for (const folder of customDemoFolders) {
          const variations = generateComponentVariations(folder.replace('Page', ''));
          const componentName = variations.componentName;
          
          console.log(`   Syncing ${variations.ComponentName}...`);
          const result = await syncCustomDemoPage(componentName, ulsPackage, projectRoot);
          results.customDemos.push({ component: variations.ComponentName, ...result });
          
          if (result.status === 'synced') {
            console.log(`      ✅ Synced (${result.masterCount} features)`);
          } else if (result.status === 'up-to-date') {
            console.log(`      ✓ Up to date`);
          } else if (result.status === 'skipped') {
            console.log(`      ⊘ ${result.reason}`);
          } else {
            console.log(`      ❌ ${result.reason}`);
          }
        }
      } else {
        console.log('   No custom demo pages found.');
      }
    } else {
      console.log('   Custom demo directory not found (skipping).');
    }
    
    // 2. Sync ULS components
    console.log('\n📦 Syncing ULS components...\n');
    const componentsResult = syncULSComponents(ulsPackage, projectRoot);
    results.components = componentsResult;
    
    if (componentsResult.status === 'skipped') {
      console.log(`   ${componentsResult.reason}`);
      if (componentsResult.note) {
        console.log(`   ℹ️  ${componentsResult.note}`);
      }
    } else {
      if (componentsResult.added.length > 0) {
        console.log(`   ✅ Added (${componentsResult.added.length}): ${componentsResult.added.join(', ')}`);
      }
      if (componentsResult.updated.length > 0) {
        console.log(`   🔄 Updated (${componentsResult.updated.length}): ${componentsResult.updated.join(', ')}`);
      }
      if (componentsResult.removed && componentsResult.removed.length > 0) {
        console.log(`   🗑️  Removed (${componentsResult.removed.length}): ${componentsResult.removed.join(', ')}`);
      }
      if (componentsResult.preserved.length > 0) {
        console.log(`   💾 Preserved (${componentsResult.preserved.length}): ${componentsResult.preserved.join(', ')}`);
      }
      if (componentsResult.customComponentsPreserved > 0) {
        console.log(`   🔒 Custom components preserved: ${componentsResult.customComponentsPreserved} (not synced)`);
      }
      if (componentsResult.ignored && componentsResult.ignored.length > 0) {
        console.log(`   🚫 Ignored (${componentsResult.ignored.length}): ${componentsResult.ignored.join(', ')} (user-deleted, not synced)`);
      }
      if (componentsResult.added.length === 0 && componentsResult.updated.length === 0 && componentsResult.preserved.length === 0 && (!componentsResult.removed || componentsResult.removed.length === 0)) {
        console.log('   ✓ All components up to date');
      }
    }
    
    // Summary
    console.log('\n' + '═'.repeat(60));
    console.log('\n📊 Sync Summary:\n');
    
    const syncedDemos = results.customDemos.filter(r => r.status === 'synced');
    const upToDateDemos = results.customDemos.filter(r => r.status === 'up-to-date');
    
    if (syncedDemos.length > 0 || upToDateDemos.length > 0) {
      console.log('Custom Demo Pages:');
      if (syncedDemos.length > 0) {
        console.log(`   ✅ Synced: ${syncedDemos.length}`);
      }
      if (upToDateDemos.length > 0) {
        console.log(`   ✓ Up to date: ${upToDateDemos.length}`);
      }
    }
    
    if (results.components && results.components.status !== 'skipped') {
      console.log('\nULS Components:');
      if (results.components.added.length > 0) {
        console.log(`   ✅ Added: ${results.components.added.length} (${results.components.added.join(', ')})`);
      }
      if (results.components.updated.length > 0) {
        console.log(`   🔄 Updated: ${results.components.updated.length} (${results.components.updated.join(', ')})`);
      }
      if (results.components.removed && results.components.removed.length > 0) {
        console.log(`   🗑️  Removed: ${results.components.removed.length} (${results.components.removed.join(', ')})`);
      }
      if (results.components.preserved.length > 0) {
        console.log(`   💾 Preserved: ${results.components.preserved.length} (${results.components.preserved.join(', ')})`);
      }
      if (results.components.customComponentsPreserved > 0) {
        console.log(`   🔒 Custom components preserved: ${results.components.customComponentsPreserved} (not synced)`);
      }
      if (results.components.ignored && results.components.ignored.length > 0) {
        console.log(`   🚫 Ignored: ${results.components.ignored.length} (${results.components.ignored.join(', ')}) - user-deleted, not synced`);
      }
    }
    
    console.log('\n✅ Sync complete!');
    console.log('\n💡 Note: Your overrides folder and custom components are preserved.');
    console.log('   Custom features in demo pages are merged at runtime.\n');
    
  } catch (error) {
    console.error('\n❌ Error:', error.message);
    if (error.stack) {
      console.error('\nStack trace:', error.stack);
    }
    process.exit(1);
  }
}

// ==========================================================================
// CLI INTERFACE
// ==========================================================================

function showHelp() {
  console.log(`
🔄 ULS Sync Utility

Usage: npm run uls-sync

What it does:
  - Syncs custom demo pages with latest master features
  - Adds new ULS components to your project
  - Updates existing ULS components
  - Preserves your custom components
  - Preserves your overrides folder (never touched)

What gets synced:
  ✅ Custom demo pages (master features only)
  ✅ ULS components (adds new, updates existing)
  
What gets preserved:
  💾 Your custom components in src/uls-components
  💾 Your custom features in custom-demo pages
  💾 Your overrides folder (completely untouched)

Note: Run "npm install" first to get latest ULS changes, then run "npm run uls-sync"
    `);
}

function main() {
  const args = process.argv.slice(2);
  
  if (args.length > 0 && (args[0] === '--help' || args[0] === '-h')) {
    showHelp();
    return;
  }
  
  syncULS();
}

// Run if called directly
if (require.main === module) {
  main();
}

module.exports = { syncULS };

